script:
(function () {
    'use strict';

    var CARD_DEFS = {
        pending_pod:              { label:'Pending POD',                    css:'tms-card--pending-pod',        icon:'📄' },
        pending_lr_no:            { label:'Pending LR No',                  css:'tms-card--pending-lr',         icon:'📋' },
        pending_dispatch:         { label:'Pending Dispatch',               css:'tms-card--pending-dispatch',   icon:'🚚' },
        pending_arrival:          { label:'Pending Arrival',                css:'tms-card--pending-arrival',    icon:'🏡' },
        pending_customer_freight: { label:'Pending Customer Freight',       css:'tms-card--pending-cf',         icon:'💰' },
        pending_vendor_freight:   { label:'Pending Vendor Freight',         css:'tms-card--pending-vf',         icon:'🚛' },
        trip_no_pending:          { label:'Trip No To Be Provided',         css:'tms-card--trip-no',            icon:'🔢' },
        trip_to_be_billed:        { label:'Trip To Be Billed',              css:'tms-card--trip-billed',        icon:'🧾' },
        original_pod_awaited:     { label:'Original POD Awaited',          css:'tms-card--pod-awaited',        icon:'📥' },
        original_pod_not_despatched: { label:'Original POD Not Despatched', css:'tms-card--pod-not-despatched', icon:'📤' },
        start_end_km_not_filled:  { label:'Start KM and End KM Not Filled', css:'tms-card--km-not-filled',      icon:'📍' },
        standard_km_not_filled:   { label:'Standard KM Not Filled',         css:'tms-card--std-km-not-filled',  icon:'📏' },
        trip_payment_awaited:     { label:'Trip Payment Awaited',          css:'tms-card--payment-awaited',   icon:'💸' },
        arrival_dispatch_blank:   { label:'Arrival/Dispatch Columns Blank', css:'tms-card--blank-cols',         icon:'⬜' },
        advance_amount_awaited:   { label:'Advance Amount Awaited',        css:'tms-card--advance-awaited',    icon:'💵' },
        balance_amount_awaited:   { label:'Balance Amount Awaited',        css:'tms-card--balance-awaited',    icon:'⚖️' }
    };

    var CARD_SETS = {
        primary: [
            'pending_pod', 'pending_lr_no', 'pending_dispatch', 'pending_arrival',
            'pending_customer_freight', 'pending_vendor_freight', 'trip_no_pending',
            'trip_to_be_billed', 'trip_payment_awaited', 'original_pod_awaited'
        ],
        secondary_market: [
            'pending_pod'
        ],
        secondary_dedicated: [
            'pending_pod', 'start_end_km_not_filled', 'standard_km_not_filled'
        ],
        other: [
            'arrival_dispatch_blank', 'original_pod_awaited', 'pending_pod',
            'advance_amount_awaited', 'balance_amount_awaited', 'original_pod_not_despatched'
        ]
    };

    var TAB_COLS = { primary: 5, other: 6 };

    function applyGridCols() {
        var cols = TAB_COLS[activeTripType];
        if (cols) {
            grid.setAttribute('data-cols', String(cols));
        } else {
            grid.removeAttribute('data-cols');
        }
    }

    function getActiveCards() {
        return (CARD_SETS[activeTripType] || CARD_SETS.primary).map(function (key) {
            var def = CARD_DEFS[key];
            return { key: key, label: def.label, css: def.css, icon: def.icon };
        });
    }

    var TRIP_TYPE_VALUES = {
        primary: 'PRIMARY',
        other: 'OTHER',
        secondary_dedicated: 'SECONDARY DEDICATED',
        secondary_market: 'SECONDARY MARKET'
    };

    // Readable filter chips for cards whose logic is a plain AND of field conditions
    // (mirrors the server-side conditions in api.py's _trip_operations_card_conditions).
    // Keyed per trip_type since the same card key (e.g. pending_pod) can have different
    // logic on different tabs. Cards not listed for a tab (arrival_dispatch_blank,
    // advance_amount_awaited, balance_amount_awaited) need OR-logic / Customer Receipt
    // Trip aggregation that Frappe's list-view filters can't express — those fall back
    // to an exact server-computed record list instead (see get_trip_operations_records).
    var ROUTE_FILTERS = {
        primary: {
            pending_pod:            [['arrival_date_time','is','set'],['pod_status','in',['POD Not Uploaded','']],['trip_status','!=','Cancel']],
            pending_lr_no:          [['lr_no','is','not set'],['trip_status','!=','Cancel']],
            pending_dispatch:       [['lr_no','is','set'],['reach_date_time','is','set'],['dispatch_date_time','is','not set'],['trip_status','!=','Cancel']],
            pending_arrival:        [['lr_no','is','set'],['dispatch_date_time','is','set'],['arrival_date_time','is','not set'],['trip_status','!=','Cancel']],
            pending_customer_freight: [['lr_no','is','set'],['customer_freight','<=',0],['bill_nodate','is','not set'],['trip_status','!=','Cancel']],
            pending_vendor_freight: [['lr_no','is','set'],['total_vendor_freight','<=',0],['vendor','!=','SADASHIV LOGISTICS PVT LTD'],['trip_status','!=','Cancel']],
                        trip_to_be_billed:      [['release_date_time','is','set'],['lr_no','is','set'],['bill_nodate','is','not set'],['bill_date','is','not set'],['trip_status','!=','Cancel']],
            trip_payment_awaited:   [['release_date_time','is','set'],['lr_no','is','set'],['bill_nodate','is','set'],['bill_date','is','set'],['date_bill_credited','is','not set'],['trip_status','!=','Cancel']],
            original_pod_awaited:   [['uploaded_pod_originalduplicate','=','Duplicate'],['pod_status','=','Duplicate POD Uploaded'],['trip_status','!=','Cancel']]
        },
        other: {
            original_pod_awaited:   [['uploaded_pod_originalduplicate','=','Duplicate'],['pod_status','=','Duplicate POD Uploaded'],['trip_status','!=','Cancel']],
            pending_pod:            [['arrival_date_time','is','set'],['pod_status','in',['POD Not Uploaded','']],['trip_status','!=','Cancel']],
            original_pod_not_despatched: [['uploaded_pod_originalduplicate','is','set'],['pod_status','in',['Original POD Uploaded','Duplicate POD Uploaded']],['date_pod_sent_to_customer','is','not set'],['trip_status','!=','Cancel']]
        },
        secondary_dedicated: {
            pending_pod:            [['arrival_date_time','is','set'],['pod_status','in',['POD Not Uploaded','']],['trip_status','!=','Cancel']],
            start_end_km_not_filled: [['start_km','is','not set'],['end_km','is','not set'],['trip_status','!=','Cancel']],
            standard_km_not_filled: [['standard_km','is','not set'],['trip_status','!=','Cancel']]
        },
        secondary_market: {
            pending_pod:            [['arrival_date_time','is','set'],['pod_status','in',['POD Not Uploaded','']],['trip_status','!=','Cancel']]
        }
    };

    var root        = root_element.getElementById('tms-ops-root');
    if (!root) return;

    var grid        = root_element.getElementById('tms-ops-grid');
    var lblUpdated  = root_element.getElementById('tms-last-updated');

    /* Filter inputs moved to the standalone "TMS Filter Bar" block:
    var selCompany  = root_element.getElementById('tms-filter-company');
    var selBranch   = root_element.getElementById('tms-filter-branch');
    var inpFrom     = root_element.getElementById('tms-filter-from');
    var inpTo       = root_element.getElementById('tms-filter-to');
    var btnSearch   = root_element.getElementById('tms-btn-search');
    var btnReset    = root_element.getElementById('tms-btn-reset');
    */

    var tabsWrap      = root_element.getElementById('tms-tt-tabs');
    var tabsHighlight = tabsWrap ? tabsWrap.querySelector('.tms-tt-tabs__highlight') : null;
    var activeTripType = 'primary';
    var lastData = {};

    // Populated by the shared "TMS Filter Bar" block via the tms-filter-changed
    // window event. This block no longer owns the filter inputs.
    var filterState = { company: '', branch: '', from_date: '', to_date: '' };

    var TAB_COLORS = {
        primary: '#6366f1',
        other: '#f59e0b',
        secondary_dedicated: '#8b5cf6',
        secondary_market: '#10b981'
    };

    function positionHighlight(el) {
        if (!tabsHighlight || !el) return;
        tabsHighlight.style.left  = el.offsetLeft + 'px';
        tabsHighlight.style.width = el.offsetWidth + 'px';
        tabsHighlight.style.background = TAB_COLORS[el.dataset.type] || '#fff';
    }

    function initTabs() {
        if (!tabsWrap) return;
        var tabs = Array.prototype.slice.call(tabsWrap.querySelectorAll('.tms-tt-tab'));
        tabs.forEach(function (tab) {
            tab.addEventListener('click', function () {
                if (tab.classList.contains('is-active')) return;
                tabs.forEach(function (t) { t.classList.remove('is-active'); t.setAttribute('aria-selected', 'false'); });
                tab.classList.add('is-active');
                tab.setAttribute('aria-selected', 'true');
                activeTripType = tab.dataset.type;
                positionHighlight(tab);
                renderSkeleton();
                fetchCounts();
            });
        });
        var activeTab = tabsWrap.querySelector('.tms-tt-tab.is-active');
        requestAnimationFrame(function () { positionHighlight(activeTab); });
        window.addEventListener('resize', function () {
            positionHighlight(tabsWrap.querySelector('.tms-tt-tab.is-active'));
        });
    }

    function renderSkeleton() {
        grid.innerHTML = '';
        applyGridCols();
        getActiveCards().forEach(function (c) {
            var el = document.createElement('div');
            el.className = 'tms-ops-card skeleton ' + c.css;
            el.innerHTML = '<span class="tms-card-icon">' + c.icon + '</span><span class="tms-card-number">&nbsp;</span><span class="tms-card-label">&nbsp;</span>';
            grid.appendChild(el);
        });
    }

    function renderCards(data) {
        grid.innerHTML = '';
        applyGridCols();
        getActiveCards().forEach(function (c) {
            var known = data && data[c.key] !== undefined;
            var display = parseInt(data && data[c.key]) || 0;
            var el = document.createElement('div');
            el.className = 'tms-ops-card ' + c.css + (known ? '' : ' tms-ops-card--pending-logic');
            el.setAttribute('role', 'button');
            el.setAttribute('tabindex', '0');
            el.innerHTML =
                '<span class="tms-card-icon">' + c.icon + '</span>' +
                '<span class="tms-card-number">' + display + '</span>' +
                '<span class="tms-card-label">' + frappe.utils.escape_html(c.label) + '</span>';
            el.addEventListener('click', function () {
                if (!known || el.classList.contains('is-loading')) return;

                function baseFilters() {
                    var f = {};
                    var co = filterState.company, br = filterState.branch;
                    var fd = filterState.from_date, td = filterState.to_date;
                    if (co) f['company'] = co;
                    if (br) f['branch']  = br;
                    if (fd && td) {
                        f['tcntrip_date'] = ['between', [fd, td]];
                    } else if (fd) {
                        f['tcntrip_date'] = ['>=', fd];
                    } else if (td) {
                        f['tcntrip_date'] = ['<=', td];
                    }
                    if (TRIP_TYPE_VALUES[activeTripType]) {
                        f['trip_type'] = TRIP_TYPE_VALUES[activeTripType];
                    }
                    return f;
                }

                var readableFilters = (ROUTE_FILTERS[activeTripType] || {})[c.key];
                if (readableFilters) {
                    // Plain AND-of-fields logic — show the real field filters, same as before.
                    var route_filters = baseFilters();
                    readableFilters.forEach(function (flt) {
                        route_filters[flt[0]] = [flt[1], flt[2]];
                    });
                    frappe.route_options = route_filters;
                    frappe.set_route('List', 'Trip');
                    return;
                }

                // OR-logic / Customer Receipt Trip aggregation — no simple field filter
                // can represent this, so fetch the exact matching Trip names instead.
                el.classList.add('is-loading');
                frappe.call({
                    method: 'logicore.logicore.api.get_trip_operations_records',
                    args: {
                        card_key: c.key,
                        company: filterState.company || '',
                        branch: filterState.branch || '',
                        from_date: filterState.from_date || '',
                        to_date: filterState.to_date || '',
                        trip_type: activeTripType || ''
                    },
                    callback: function (r) {
                        el.classList.remove('is-loading');
                        var names = (r && r.message) || [];
                        var route_filters = baseFilters();
                        route_filters['name'] = ['in', names.length ? names : ['__tms_no_match__']];
                        frappe.route_options = route_filters;
                        frappe.set_route('List', 'Trip');
                    },
                    error: function () {
                        el.classList.remove('is-loading');
                    }
                });
            });
            grid.appendChild(el);
        });
        if (lblUpdated) lblUpdated.textContent = 'Updated ' + new Date().toLocaleTimeString();
    }

    function fetchCounts() {
        root_element.querySelectorAll('.tms-card-number').forEach(function (el) { el.classList.add('refreshing'); });
        frappe.call({
            method: 'logicore.logicore.api.get_trip_operations_summary',
            args: {
                company: filterState.company || '',
                branch: filterState.branch || '',
                from_date: filterState.from_date || '',
                to_date: filterState.to_date || '',
                trip_type: activeTripType || ''
            },
            callback: function (r) {
                lastData = r && r.message ? r.message : {};
                renderCards(lastData);
            },
            error: function () {
                lastData = {};
                renderCards(lastData);
            }
        });
    }

    // The shared "TMS Filter Bar" block dispatches this on load, Search, and Reset.
    window.addEventListener('tms-filter-changed', function (e) {
        var d = (e && e.detail) || {};
        filterState.company   = d.company   || '';
        filterState.branch    = d.branch    || '';
        filterState.from_date = d.from_date || '';
        filterState.to_date   = d.to_date   || '';
        renderSkeleton();
        fetchCounts();
    });

    /* Filter population, Search/Reset wiring and default dates moved to the
       standalone "TMS Filter Bar" block:
    function dispatchFilterEvent() { ... }
    function populateFilters() { ... }
    btnSearch.addEventListener('click', fetchCounts);
    btnReset.addEventListener('click', function () {
        selCompany.value = ''; selBranch.value = ''; inpFrom.value = ''; inpTo.value = '';
        fetchCounts();
    });
    [inpFrom, inpTo].forEach(function (i) { i.addEventListener('keydown', function (e) { if (e.key === 'Enter') fetchCounts(); }); });
    var _now = new Date(), _y = _now.getFullYear(), _m = _now.getMonth();
    function _fmt(d) { ... }
    inpFrom.value = _fmt(new Date(_y, _m, 1));
    inpTo.value   = _fmt(new Date(_y, _m + 1, 0));
    populateFilters();
    */

    renderSkeleton();
    initTabs();

}());

(function(){
    'use strict';
    var btnDl  = root_element.getElementById('vp-download');
    var tbody  = root_element.getElementById('vp-tbody');
    var empty  = root_element.getElementById('vp-empty');
    var table  = root_element.getElementById('vp-table');
    var lblUpd = root_element.getElementById('vp-updated');

    if (!tbody) return;

    function _dmy(s){ return s ? s.split('-').reverse().join('-') : ''; }
    function _inr(n){ return '₹'+(parseFloat(n)||0).toLocaleString('en-IN',{minimumFractionDigits:0,maximumFractionDigits:0}); }
    function _esc(s){ return frappe.utils.escape_html(s||''); }

    // Last values broadcast by the shared "TMS Filter Bar" block. Kept separate from
    // what was actually sent so that un-ticking Show All can restore them.
    var _filter = { from_date:'', to_date:'', company:'', branch:'' };
    var _showAll = false;
    var _data = [];

    function renderRows(rows){
        _data = (rows || []).slice().sort(function(a, b){
    return (a.vendor || '').localeCompare(b.vendor || '', undefined, { numeric: true, sensitivity: 'base' });
});
        tbody.innerHTML = '';
        if (!_data.length){
            table.style.display = 'none';
            empty.style.display = '';
            return;
        }
        table.style.display = '';
        empty.style.display = 'none';
        _data.forEach(function(r,i){
            var tr = document.createElement('tr');
            tr.innerHTML =
                '<td style="color:var(--text-muted);font-size:12px;">'+(i+1)+'</td>'+
                '<td><a class="vp-vendor-link" href="#" data-vendor="'+_esc(r.vendor)+'">'+_esc(r.vendor)+'</a></td>'+
                '<td>'+_esc(r.vendor_type||'')+'</td>'+
                '<td style="text-align:right;" class="vp-amt">'+_inr(r.total_freight)+'</td>'+
                '<td style="text-align:right;" class="vp-amt">'+_inr(r.paid_amount)+'</td>'+
                '<td style="text-align:right;"><span class="vp-balance">'+_inr(r.balance)+'</span></td>'+
                '<td style="text-align:center;">'+_dmy(r.oldest_trip_date ? String(r.oldest_trip_date).slice(0,10) : '')+'</td>';
            tr.querySelector('.vp-vendor-link').addEventListener('click', function(e){
                e.preventDefault();
                frappe.set_route('List','Trip',{'vendor': this.dataset.vendor});
            });
            tbody.appendChild(tr);
        });
        if (lblUpd) lblUpd.textContent = 'Updated '+new Date().toLocaleTimeString();
    }

    function fetchData(fromDate, toDate, company, branch){
        frappe.call({
            method: 'logicore.logicore.api.get_vendor_pending_summary',
            args: {
                from_date: fromDate || '',
                to_date:   toDate   || '',
                company:   company  || '',
                branch:    branch   || ''
            },
            callback: function(r){
                renderRows(r && r.message ? r.message : []);
            },
            error: function(){
                renderRows([]);
            }
        });
    }

    function applyFilter(){
        if (_showAll) {
            fetchData('', '', '', '');
        } else {
            fetchData(_filter.from_date, _filter.to_date, _filter.company, _filter.branch);
        }
    }

    btnDl.addEventListener('click', function(){
        if (!_data.length) return;
        var header = ['#','Vendor Name','Type','Total Freight','Paid Amount','Balance Amount','Older Bill/Trip Date'];
        var lines  = [header.join(',')];
        _data.forEach(function(r,i){
            lines.push([
                i+1,
                '"'+(r.vendor||'').replace(/"/g,'""')+'"',
                '"'+(r.vendor_type||'').replace(/"/g,'""')+'"',
                parseFloat(r.total_freight)||0,
                parseFloat(r.paid_amount)||0,
                parseFloat(r.balance)||0,
                r.oldest_trip_date ? String(r.oldest_trip_date).slice(0,10) : ''
            ].join(','));
        });
        var blob = new Blob([lines.join('\n')], {type:'text/csv'});
        var url  = URL.createObjectURL(blob);
        var a    = document.createElement('a');
        a.href = url;
        a.download = _showAll
            ? 'vendor_pending_all.csv'
            : 'vendor_pending_'+_filter.from_date+'_to_'+_filter.to_date+'.csv';
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
    });

    var cbShowAll = root_element.getElementById('tvp-show-all');
    if (cbShowAll) {
        cbShowAll.checked = _showAll;
        cbShowAll.addEventListener('change', function() {
            _showAll = this.checked;
            applyFilter();
        });
    }

    window.addEventListener('tms-filter-changed', function(e) {
        var d = (e && e.detail) || {};
        _filter.from_date = d.from_date || '';
        _filter.to_date   = d.to_date   || '';
        _filter.company   = d.company   || '';
        _filter.branch    = d.branch    || '';
        // A new filter selection always wins over Show All — untick it so the
        // table follows the shared filter again.
        _showAll = false;
        if (cbShowAll) cbShowAll.checked = false;
        applyFilter();
    });
}());

(function(){
    'use strict';

    var btnDownload = root_element.getElementById('tmo-download');
    var table = root_element.getElementById('tmo-table');
    var tbody = root_element.getElementById('tmo-tbody');
    var empty = root_element.getElementById('tmo-empty');
    var updated = root_element.getElementById('tmo-updated');

    if (!tbody) return;

    /* Default-date helper no longer needed here — the "TMS Filter Bar" block owns default dates:
    function fmtDate(d) {
        return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');
    }
    */

    function dmy(value) {
        return value ? String(value).slice(0, 10).split('-').reverse().join('-') : '';
    }

    function money(value) {
        var n = parseFloat(value) || 0;
        var sign = n < 0 ? '− ' : '';
        return sign + '₹' + Math.abs(n).toLocaleString('en-IN', { minimumFractionDigits: 0, maximumFractionDigits: 0 });
    }

    function esc(value) {
        return frappe.utils.escape_html(value || '');
    }

    // Last values broadcast by the shared "TMS Filter Bar" block. Kept separate from
    // what was actually sent so that un-ticking Show All can restore them.
    var _filter = { from_date:'', to_date:'', company:'', branch:'' };
    var showAll = false;
    var dataRows = [];

    function renderRows(rows) {
        dataRows = (rows || []).slice();
        tbody.innerHTML = '';

        if (!dataRows.length) {
            table.style.display = 'none';
            empty.style.display = '';
            if (updated) updated.textContent = 'Updated ' + new Date().toLocaleTimeString();
            return;
        }

        table.style.display = '';
        empty.style.display = 'none';

        dataRows.forEach(function (row, index) {
            var tr = document.createElement('tr');
            tr.innerHTML =
                '<td style="padding:9px 12px;color:var(--text-muted);border-bottom:1px solid var(--border-color);">' + (index + 1) + '</td>' +
                '<td style="padding:9px 12px;border-bottom:1px solid var(--border-color);white-space:nowrap;">' + dmy(row.trip_date) + '</td>' +
                '<td style="padding:9px 12px;border-bottom:1px solid var(--border-color);white-space:nowrap;"><a href="#" class="tmo-trip-link" data-name="' + esc(row.name) + '" style="color:var(--primary,#2196F3);text-decoration:none;font-weight:600;">' + esc(row.trip_no) + '</a></td>' +
                '<td style="padding:9px 12px;border-bottom:1px solid var(--border-color);min-width:180px;">' + esc(row.origin_city) + '</td>' +
                '<td style="padding:9px 12px;border-bottom:1px solid var(--border-color);min-width:180px;">' + esc(row.destination_city) + '</td>' +
                '<td style="padding:9px 12px;border-bottom:1px solid var(--border-color);white-space:nowrap;">' + esc(row.lr_no) + '</td>' +
                '<td style="padding:9px 12px;border-bottom:1px solid var(--border-color);white-space:nowrap;">' + esc(row.vehicle_no) + '</td>' +
                '<td style="padding:9px 12px;border-bottom:1px solid var(--border-color);text-align:right;white-space:nowrap;">' + money(row.freight) + '</td>' +
                '<td style="padding:9px 12px;border-bottom:1px solid var(--border-color);text-align:right;white-space:nowrap;">' + money(row.approved_addl_amount) + '</td>' +
                '<td style="padding:9px 12px;border-bottom:1px solid var(--border-color);text-align:right;white-space:nowrap;font-weight:600;">' + money(row.total_trip_amount) + '</td>' +
                '<td style="padding:9px 12px;border-bottom:1px solid var(--border-color);text-align:right;white-space:nowrap;color:#e17055;">' + (parseFloat(row.brokerage_amount)||0 ? money(row.brokerage_amount) : '—') + '</td>' +
                '<td style="padding:9px 12px;border-bottom:1px solid var(--border-color);text-align:right;white-space:nowrap;color:#e17055;">' + (parseFloat(row.broker_lr)||0 ? money(row.broker_lr) : '—') + '</td>' +
                '<td style="padding:9px 12px;border-bottom:1px solid var(--border-color);text-align:right;white-space:nowrap;color:#e17055;">' + (parseFloat(row.tds_amount)||0 ? money(row.tds_amount) : '—') + '</td>' +
                '<td style="padding:9px 12px;border-bottom:1px solid var(--border-color);text-align:right;white-space:nowrap;font-weight:600;">' + money(row.net_receive_amount) + '</td>' +
                '<td style="padding:9px 12px;border-bottom:1px solid var(--border-color);text-align:right;white-space:nowrap;color:#00b894;font-weight:700;">' + money(row.amount_received) + '</td>' +
                '<td style="padding:9px 12px;border-bottom:1px solid var(--border-color);text-align:right;white-space:nowrap;font-weight:700;color:' + ((parseFloat(row.balance_amt)||0) > 0.01 ? '#d32f2f' : '#00b894') + ';">' + money(row.balance_amt) + '</td>';

            tr.querySelector('.tmo-trip-link').addEventListener('click', function (e) {
                e.preventDefault();
                frappe.set_route('Form', 'Trip', this.dataset.name);
            });

            tbody.appendChild(tr);
        });

        if (updated) updated.textContent = 'Updated ' + new Date().toLocaleTimeString();
    }

    function fetchData(fromDate, toDate, company, branch) {
        frappe.call({
            method: 'logicore.logicore.api.get_trip_other_summary',
            args: {
                from_date: fromDate || '',
                to_date:   toDate   || '',
                company:   company  || '',
                branch:    branch   || ''
            },
            callback: function (r) {
                renderRows(r && r.message ? r.message : []);
            },
            error: function () {
                renderRows([]);
            }
        });
    }

    function applyFilter() {
        if (showAll) {
            fetchData('', '', '', '');
        } else {
            fetchData(_filter.from_date, _filter.to_date, _filter.company, _filter.branch);
        }
    }

    function downloadCsv() {
        if (!dataRows.length) return;
        var header = ['#', 'Date', 'Trip No', 'Origin City', 'Destination City', 'LR No', 'Vehicle No', 'Freight', 'Total Approved Amount', 'Total Trip Cost', 'Brokerage', 'Broker LR', 'TDS', 'Net Receive Amount', 'Amt Received', 'Balance Amt'];
        var lines = [header.join(',')];
        dataRows.forEach(function (row, index) {
            lines.push([
                index + 1,
                '"' + String(row.trip_date || '').replace(/"/g, '""') + '"',
                '"' + String(row.trip_no || '').replace(/"/g, '""') + '"',
                '"' + String(row.origin_city || '').replace(/"/g, '""') + '"',
                '"' + String(row.destination_city || '').replace(/"/g, '""') + '"',
                '"' + String(row.lr_no || '').replace(/"/g, '""') + '"',
                '"' + String(row.vehicle_no || '').replace(/"/g, '""') + '"',
                parseFloat(row.freight) || 0,
                parseFloat(row.approved_addl_amount) || 0,
                parseFloat(row.total_trip_amount) || 0,
                parseFloat(row.brokerage_amount) || 0,
                parseFloat(row.broker_lr) || 0,
                parseFloat(row.tds_amount) || 0,
                parseFloat(row.net_receive_amount) || 0,
                parseFloat(row.amount_received) || 0,
                parseFloat(row.balance_amt) || 0
            ].join(','));
        });

        var blob = new Blob([lines.join('\n')], { type: 'text/csv' });
        var url = URL.createObjectURL(blob);
        var a = document.createElement('a');
        a.href = url;
        a.download = showAll
            ? 'trip_other_all.csv'
            : 'trip_other_' + _filter.from_date + '_to_' + _filter.to_date + '.csv';
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
    }

    var cbShowAll = root_element.getElementById('tmo-show-all');
    if (cbShowAll) {
        cbShowAll.checked = showAll;
        cbShowAll.addEventListener('change', function() {
            showAll = this.checked;
            applyFilter();
        });
    }

    window.addEventListener('tms-filter-changed', function(e) {
        var d = (e && e.detail) || {};
        _filter.from_date = d.from_date || '';
        _filter.to_date   = d.to_date   || '';
        _filter.company   = d.company   || '';
        _filter.branch    = d.branch    || '';
        // A new filter selection always wins over Show All — untick it so the
        // table follows the shared filter again.
        showAll = false;
        if (cbShowAll) cbShowAll.checked = false;
        applyFilter();
    });

    btnDownload.addEventListener('click', downloadCsv);
}());

