(function () {
    'use strict';

    var CARDS = [
        {
            key: 'active_finance_vehicles',
            label: 'Active Finance Vehicles',
            css: 'vfa-ops-card--active',
            icon: '🏦',
            subtitle: 'Loans currently running',
            clickFn: function () {
                var today = new Date().toISOString().slice(0, 10);
                frappe.route_options = { end_date: ['>=', today], start_date: ['<=', today] };
                frappe.set_route('List', 'Vehicle Finance');
            }
        },
        {
            key: 'emi_in_period',
            label: 'EMI Transferred',
            css: 'vfa-ops-card--emi',
            icon: '💳',
            subtitle: 'Vehicle Finance EMI – Status: Paid',
            clickFn: function (from, to) {
                var opts = { type: 'Vehicle Finance EMI', status: 'Paid' };
                if (from && to) opts['date'] = ['between', [from, to]];
                else if (from)  opts['date'] = ['>=', from];
                else if (to)    opts['date'] = ['<=', to];
                frappe.route_options = opts;
                frappe.set_route('List', 'Payment');
            }
        },
        {
            key: 'emi_draft_payments',
            label: 'EMI Payment in Draft',
            css: 'vfa-ops-card--draft',
            icon: '⏳',
            subtitle: 'Vehicle Finance EMI – Status: Draft',
            clickFn: function (from, to) {
                var opts = { type: 'Vehicle Finance EMI', status: 'Draft', reference_no: ['is', 'not set'] };
                if (from && to) opts['date'] = ['between', [from, to]];
                else if (from)  opts['date'] = ['>=', from];
                else if (to)    opts['date'] = ['<=', to];
                frappe.route_options = opts;
                frappe.set_route('List', 'Payment');
            }
        }
    ];

    var root       = root_element.getElementById('vfa-root');
    if (!root) return;

    var grid       = root_element.getElementById('vfa-ops-grid');
    var lblUpdated = root_element.getElementById('vfa-last-updated');

    var now = new Date();
    var currentFrom = now.getFullYear() + '-' + String(now.getMonth() + 1).padStart(2, '0') + '-01';
    var lastDay = new Date(now.getFullYear(), now.getMonth() + 1, 0).getDate();
    var currentTo = now.getFullYear() + '-' + String(now.getMonth() + 1).padStart(2, '0') + '-' + String(lastDay).padStart(2, '0');

    function renderSkeleton() {
        grid.innerHTML = '';
        CARDS.forEach(function (c) {
            var el = document.createElement('div');
            el.className = 'vfa-ops-card skeleton ' + c.css;
            el.innerHTML =
                '<span class="vfa-card-icon">' + c.icon + '</span>' +
                '<span class="vfa-card-number">&nbsp;</span>' +
                '<span class="vfa-card-label">&nbsp;</span>' +
                '<span class="vfa-card-subtitle">&nbsp;</span>';
            grid.appendChild(el);
        });
    }

    function renderCards(data) {
        grid.innerHTML = '';
        CARDS.forEach(function (c) {
            var count = (data && data[c.key] !== undefined) ? parseInt(data[c.key]) || 0 : 0;
            var el = document.createElement('div');
            el.className = 'vfa-ops-card ' + c.css;
            el.setAttribute('role', 'button');
            el.setAttribute('tabindex', '0');
            el.innerHTML =
                '<span class="vfa-card-icon">' + c.icon + '</span>' +
                '<span class="vfa-card-number">' + count + '</span>' +
                '<span class="vfa-card-label">' + frappe.utils.escape_html(c.label) + '</span>' +
                '<span class="vfa-card-subtitle">' + frappe.utils.escape_html(c.subtitle) + '</span>';
            (function (card) {
                el.addEventListener('click', function () { card.clickFn(currentFrom, currentTo); });
                el.addEventListener('keydown', function (e) { if (e.key === 'Enter' || e.key === ' ') card.clickFn(currentFrom, currentTo); });
            })(c);
            grid.appendChild(el);
        });
        if (lblUpdated) lblUpdated.textContent = 'Updated ' + new Date().toLocaleTimeString();
    }

    function fetchData() {
        grid.querySelectorAll('.vfa-card-number').forEach(function (el) { el.classList.add('refreshing'); });
        frappe.call({
            method: 'logicore.logicore.api.get_vehicle_finance_activity_summary',
            args: { from_date: currentFrom, to_date: currentTo },
            callback: function (r) { renderCards(r && r.message ? r.message : {}); },
            error:    function ()  { renderCards({}); }
        });
    }

    window.addEventListener('tms-filter-changed', function (e) {
        var d = (e && e.detail) || {};
        if (d.from_date) currentFrom = d.from_date;
        if (d.to_date)   currentTo   = d.to_date;
        fetchData();
    });

    renderSkeleton();
    // Small delay so tms-filter-changed from Trip Operations sets dates first
    setTimeout(fetchData, 400);

}());

(function () {
    'use strict';

    var root = root_element.getElementById('tms-filter-root');
    if (!root) return;

    var selCompany = root_element.getElementById('tms-filter-company');
    var selBranch  = root_element.getElementById('tms-filter-branch');
    var inpFrom    = root_element.getElementById('tms-filter-from');
    var inpTo      = root_element.getElementById('tms-filter-to');
    var btnSearch  = root_element.getElementById('tms-btn-search');
    var btnReset   = root_element.getElementById('tms-btn-reset');

    function _fmt(d) { return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0'); }

    function dispatchFilterEvent() {
        window.dispatchEvent(new CustomEvent('tms-filter-changed', {
            detail: {
                from_date: inpFrom.value || '',
                to_date:   inpTo.value   || '',
                company:   selCompany.value || '',
                branch:    selBranch.value  || ''
            }
        }));
    }

    function populateFilters() {
        frappe.call({
            method: 'logicore.logicore.api.get_trip_filter_options',
            callback: function (r) {
                if (r && r.message) {
                    (r.message.companies || []).forEach(function (c) {
                        var o = document.createElement('option');
                        o.value = c.value; o.textContent = c.label;
                        selCompany.appendChild(o);
                    });
                    (r.message.branches || []).forEach(function (b) {
                        var o = document.createElement('option');
                        o.value = b.value; o.textContent = b.label;
                        selBranch.appendChild(o);
                    });
                    var def = frappe.defaults.get_user_default('company') || frappe.defaults.get_default('company') || '';
                    if (def) selCompany.value = def;
                }
                dispatchFilterEvent();
            }
        });
    }

    btnSearch.addEventListener('click', dispatchFilterEvent);
    btnReset.addEventListener('click', function () {
        selCompany.value = ''; selBranch.value = ''; inpFrom.value = ''; inpTo.value = '';
        dispatchFilterEvent();
    });
    [inpFrom, inpTo].forEach(function (i) {
        i.addEventListener('keydown', function (e) { if (e.key === 'Enter') dispatchFilterEvent(); });
    });

    var _now = new Date(), _y = _now.getFullYear(), _m = _now.getMonth();
    inpFrom.value = _fmt(new Date(_y, _m, 1));
    inpTo.value   = _fmt(new Date(_y, _m + 1, 0));

    populateFilters();

}());
